/** Repair catalog and previously saved project-scoped links without touching custom uploads or other media. */
export function repairWallpaperUrl(src: string | undefined, kind: "image" | "video"): string | undefined {
  if (!src || src.startsWith("blob:") || src.startsWith("data:")) return src;
  try {
    const path = new URL(src, "https://wallpaper.local").pathname;
    if (!path.includes("/__l5e/assets-v1/")) return src;
    const filename = decodeURIComponent(path.split("/").pop() ?? "");
    const stem = filename.replace(/\.(?:mp4|webm|jpe?g|png|webp|avif)$/i, "").replace(/-native$/i, "");
    const live = WALLPAPER_LIVE_SOURCES[stem];
    return live ? live[kind] : src;
  } catch { return src; }
}
